"""Shared-car booking helpers."""

__all__ = ["is_free", "quote_cents", "assign"]


def is_free(bookings, car, start, end):
    """Return True if `car` is free for the whole interval [start, end)."""
    if end < start:
        return False
    if start == end:
        return True

    for booking in bookings:
        if booking.get("status") != "confirmed":
            continue
        if booking.get("car") != car:
            continue

        b_start = booking.get("start")
        b_end = booking.get("end")
        if b_start is None or b_end is None:
            continue
        if b_end <= b_start:
            continue

        if b_start < end and start < b_end:
            return False

    return True


def quote_cents(start, end, tz, hourly_cents, day_cap_cents):
    """Return the price in cents for booking [start, end)."""
    if end <= start or hourly_cents <= 0:
        return 0

    cap = max(0, int(day_cap_cents))
    if cap == 0:
        return 0

    first_day = (start + tz) // 1440
    last_day = (end - 1 + tz) // 1440

    total = 0
    for day in range(first_day, last_day + 1):
        day_start = day * 1440 - tz
        day_end = day_start + 1440

        seg_start = max(start, day_start)
        seg_end = min(end, day_end)
        minutes = seg_end - seg_start

        if minutes <= 0:
            continue

        charge = (minutes * hourly_cents + 59) // 60
        if charge > cap:
            charge = cap
        total += charge

    return total


def assign(cars, bookings, requests, tz, hourly_cents, day_cap_cents):
    """Assign requests to cars, processing by submission time."""
    current_bookings = list(bookings)
    results = [None] * len(requests)

    ordered = sorted(
        enumerate(requests),
        key=lambda item: (item[1].get("at", 0), item[0]),
    )

    for index, request in ordered:
        request_id = request.get("id")
        needed_seats = request.get("seats", 0)
        start = request["start"]
        end = request["end"]

        chosen_car = None
        for car in cars:
            if car.get("seats", 0) < needed_seats:
                continue

            car_id = car.get("id")
            if is_free(current_bookings, car_id, start, end):
                chosen_car = car_id
                break

        if chosen_car is None:
            results[index] = {
                "request": request_id,
                "car": None,
                "price_cents": 0,
            }
            continue

        price = quote_cents(start, end, tz, hourly_cents, day_cap_cents)
        results[index] = {
            "request": request_id,
            "car": chosen_car,
            "price_cents": price,
        }

        current_bookings.append({
            "car": chosen_car,
            "member": request.get("member"),
            "start": start,
            "end": end,
            "status": "confirmed",
        })

    return results
