def pick_next(history, library) -> str:
    """
    Return the id of the next song to play.
    Chooses an unplayed song with BPM closest to the last played song's BPM.
    If all songs have been played, starts a new cycle, avoiding immediate repeat if possible.
    Returns "" if library is empty or no valid songs.
    """
    if not library:
        return ""

    # Build list of valid songs (id: str, bpm: int)
    songs = []
    for entry in library:
        if not isinstance(entry, dict):
            continue
        sid = entry.get("id")
        bpm = entry.get("bpm")
        if not isinstance(sid, str):
            continue
        try:
            bpm_int = int(bpm)
        except (TypeError, ValueError):
            bpm_int = None
        songs.append({"id": sid, "bpm": bpm_int})

    if not songs:
        return ""

    # Map id to bpm for history lookup (first occurrence wins)
    bpm_by_id = {}
    for s in songs:
        if s["bpm"] is not None and s["id"] not in bpm_by_id:
            bpm_by_id[s["id"]] = s["bpm"]

    # Determine last played BPM
    last_bpm = None
    if history:
        last_id = history[-1]
        if last_id in bpm_by_id:
            last_bpm = bpm_by_id[last_id]

    played = set(history) if history else set()

    # Candidates not played
    candidates = [s for s in songs if s["id"] not in played]

    if not candidates:
        # All played: start new cycle, avoid immediate repeat of last id if possible
        last_id = history[-1] if history else None
        if last_id is not None and len(songs) > 1:
            candidates = [s for s in songs if s["id"] != last_id]
            if not candidates:  # fallback (should not happen if len(songs) > 1)
                candidates = songs
        else:
            candidates = songs

    # If no last_bpm, just pick the first candidate
    if last_bpm is None:
        return candidates[0]["id"]

    # Pick candidate with BPM closest to last_bpm; tie-break by library order
    best = None
    best_diff = None
    for s in candidates:
        if s["bpm"] is None:
            diff = float("inf")
        else:
            diff = abs(s["bpm"] - last_bpm)
        if best is None or diff < best_diff:
            best = s
            best_diff = diff

    return best["id"] if best else ""


def blend(a, b, overlap) -> list:
    """
    Join two sample lists, mixing the last `overlap` samples of a with the first
    `overlap` samples of b. Overlapping samples are summed and clipped to [-1.0, 1.0].
    If overlap is negative or zero, simply concatenate. If overlap exceeds the
    length of either list, it is clamped to the shorter length.
    """
    try:
        ov = int(overlap)
    except (TypeError, ValueError):
        ov = 0

    if ov < 0:
        ov = 0
    ov = min(ov, len(a), len(b))

    if ov == 0:
        return [float(x) for x in a] + [float(x) for x in b]

    result = [float(x) for x in a[:-ov]]
    for i in range(ov):
        sample = float(a[-ov + i]) + float(b[i])
        if sample > 1.0:
            sample = 1.0
        elif sample < -1.0:
            sample = -1.0
        result.append(sample)
    result.extend(float(x) for x in b[ov:])
    return result
