def due_doses(meds, taken, now, tz) -> list:
    local_now_abs = now + tz
    current_day_index = local_now_abs // 1440
    local_now_time = local_now_abs % 1440

    # Group taken records by med, convert to local absolute minutes, only past taps
    taken_by_med = {}
    for t in taken:
        if not isinstance(t, dict):
            continue
        med_name = t.get("med")
        at = t.get("at")
        if med_name is None or at is None:
            continue
        try:
            at_int = int(at)
        except (TypeError, ValueError):
            continue
        at_local = at_int + tz
        if at_local <= local_now_abs:
            taken_by_med.setdefault(med_name, []).append(at_local)
    for lst in taken_by_med.values():
        lst.sort()

    result = []
    for med in meds:
        if not isinstance(med, dict):
            continue
        name = med.get("name")
        if name is None:
            continue
        times = med.get("times", [])
        if not isinstance(times, list):
            continue

        # Determine due times and keep original indices
        due = []  # (time, original_index)
        for idx, t in enumerate(times):
            try:
                t_int = int(t)
            except (TypeError, ValueError):
                continue
            if t_int <= local_now_time:
                due.append((t_int, idx))
        if not due:
            continue

        # Match taken records to the most recent due dose at or before the tap time
        due_sorted = sorted(due, key=lambda x: x[0])  # ascending by time
        marked = [False] * len(due_sorted)
        taken_list = taken_by_med.get(name, [])
        for taken_time in taken_list:
            for k in range(len(due_sorted) - 1, -1, -1):
                dose_abs = current_day_index * 1440 + due_sorted[k][0]
                if not marked[k] and dose_abs <= taken_time:
                    marked[k] = True
                    break

        # Create set of taken original indices
        taken_indices = {due_sorted[k][1] for k in range(len(due_sorted)) if marked[k]}

        # Output unmarked due doses in original order
        for t_int, idx in due:
            if idx not in taken_indices:
                result.append({"med": name, "time": t_int})
    return result
