def weekly_pay(shifts, rate_cents_per_hour) -> int:
    """
    Compute total weekly pay in integer cents.
    Shifts are merged to avoid double-counting overlapping intervals.
    Only minutes within the week [0, 10080) are paid.
    Pay is calculated from total minutes and rounded half-up to the nearest cent.
    """
    WEEK_MINUTES = 7 * 1440
    intervals = []

    for shift in shifts:
        if not isinstance(shift, dict):
            continue
        start = shift.get("start")
        end = shift.get("end")
        if start is None or end is None:
            continue
        try:
            start_int = int(start)
            end_int = int(end)
        except (TypeError, ValueError):
            continue
        if end_int <= start_int:
            continue
        # Clamp to the current week
        start_int = max(start_int, 0)
        end_int = min(end_int, WEEK_MINUTES)
        if end_int <= start_int:
            continue
        intervals.append((start_int, end_int))

    if not intervals:
        return 0

    # Merge overlapping or touching intervals
    intervals.sort(key=lambda x: x[0])
    merged = []
    cur_start, cur_end = intervals[0]
    for start, end in intervals[1:]:
        if start <= cur_end:
            if end > cur_end:
                cur_end = end
        else:
            merged.append((cur_start, cur_end))
            cur_start, cur_end = start, end
    merged.append((cur_start, cur_end))

    total_minutes = sum(end - start for start, end in merged)

    try:
        rate = int(rate_cents_per_hour)
    except (TypeError, ValueError):
        rate = 0

    # Round half-up to nearest cent: (total_minutes * rate + 30) // 60
    total_cents = (total_minutes * rate + 30) // 60
    return total_cents
