def prune_backups(backups, now, free_mb, min_free_mb):
    DAY = 1440
    to_delete = set()
    retained = []
    # Mark corrupt and backups older than 28 days for deletion.
    for b in backups:
        age = now - b["time"]
        if not b.get("ok", True):
            to_delete.add(b["id"])
        elif age >= 28 * DAY:
            to_delete.add(b["id"])
    # Keep newest OK backup in each 7-day block between 7 and 28 days old.
    for low, high in ((7, 14), (14, 21), (21, 28)):
        candidates = []
        for b in backups:
            if not b.get("ok", True):
                continue
            age = now - b["time"]
            if low * DAY <= age < high * DAY:
                candidates.append(b)
        if candidates:
            keep = max(candidates, key=lambda x: x["time"])
            for b in candidates:
                if b["id"] != keep["id"]:
                    to_delete.add(b["id"])
            retained.append(keep)
    # Keep all OK backups from the last 7 days.
    for b in backups:
        if b.get("ok", True):
            age = now - b["time"]
            if age < 7 * DAY:
                retained.append(b)
    # If there is not enough free space, delete oldest retained backups first.
    freed = sum(b["size_mb"] for b in backups if b["id"] in to_delete)
    projected_free = free_mb + freed
    if projected_free < min_free_mb:
        retained_by_id = {b["id"]: b for b in retained if b["id"] not in to_delete}
        extra = sorted(retained_by_id.values(), key=lambda b: (b["time"], b["id"]))
        for b in extra:
            if projected_free >= min_free_mb:
                break
            to_delete.add(b["id"])
            projected_free += b["size_mb"]
    return [b["id"] for b in backups if b["id"] in to_delete]
