def _find_slot_continuous(candidate, duration, occupied):
    if duration <= 0:
        return candidate
    busy = sorted(occupied)
    cur = candidate
    for bs, be in busy:
        if be <= cur:
            continue
        if bs - cur >= duration:
            return cur
        if be > cur:
            cur = be
    return cur


def _find_slot(candidate, duration, occupied, tz):
    if duration <= 0:
        return candidate
    if duration > WORK_END - WORK_START:
        return _find_slot_continuous(candidate, duration, occupied)
    local_candidate = candidate + tz
    day = local_candidate // 1440
    for d in range(day, day + 10000):
        dow = d % 7
        if dow not in WORKDAYS:
            continue
        ws_local = d * 1440 + WORK_START
        we_local = d * 1440 + WORK_END
        ws = ws_local - tz
        we = we_local - tz
        if we <= candidate:
            continue
        start_min = max(candidate, ws)
        if start_min + duration > we:
            continue
        busy = []
        for bs, be in occupied:
            if be <= start_min or bs >= we:
                continue
            busy.append((max(bs, start_min), min(be, we)))
        busy.sort()
        cur = start_min
        for bs, be in busy:
            if be <= cur:
                continue
            if bs - cur >= duration:
                return cur
            if be > cur:
                cur = be
            if cur + duration > we:
                break
        if cur + duration <= we:
            return cur
    return _find_slot_continuous(candidate, duration, occupied)


def _is_free(start, duration, occupied):
    end = start + duration
    for bs, be in occupied:
        if start < be and bs < end:
            return False
    return True


def plan_meetings(requests, existing, now, tz):
    occupied = []
    for iv in existing:
        s = int(iv["start"])
        e = int(iv["end"])
        if s > e:
            s, e = e, s
        if s < e:
            occupied.append((s, e))
    result = []
    for req in requests:
        rid = req["id"]
        duration = int(req.get("duration", 0))
        if duration < 0:
            duration = 0
        requested_start = req.get("start")
        if requested_start is not None:
            s = int(requested_start)
            if s >= now and (duration <= 0 or _is_free(s, duration, occupied)):
                book_start = s
            else:
                candidate = s if s >= now else now
                book_start = _find_slot(candidate, duration, occupied, tz)
        else:
            book_start = _find_slot(now, duration, occupied, tz)
        result.append({"id": rid, "start": book_start})
        if duration > 0:
            occupied.append((book_start, book_start + duration))
    return result
