from collections import deque


def loyalty_balance(events, today):
    kind_priority = {"earn": 0, "redeem": 1, "reverse": 2}
    sorted_events = sorted(
        events,
        key=lambda e: (e["day"], kind_priority.get(e["kind"], 3), e["id"]),
    )
    id_to_idx = {ev["id"]: i for i, ev in enumerate(sorted_events)}
    cancelled = set()
    active = {}
    for i in range(len(sorted_events) - 1, -1, -1):
        ev = sorted_events[i]
        eid = ev["id"]
        if eid in cancelled:
            active[eid] = False
        else:
            active[eid] = True
            if ev["kind"] == "reverse":
                target = ev.get("of")
                if target in id_to_idx and id_to_idx[target] < i:
                    cancelled.add(target)
    lots = deque()
    for ev in sorted_events:
        if not active.get(ev["id"], False):
            continue
        kind = ev["kind"]
        if kind == "earn":
            day = ev["day"]
            while lots and day - lots[0][0] >= 365:
                lots.popleft()
            pts = int(ev.get("points", 0))
            if pts > 0:
                lots.append([day, pts])
        elif kind == "redeem":
            day = ev["day"]
            while lots and day - lots[0][0] >= 365:
                lots.popleft()
            pts = int(ev.get("points", 0))
            if pts < 100:
                continue
            total = sum(p for _, p in lots)
            if total < pts:
                continue
            remaining = pts
            while remaining > 0 and lots:
                lot = lots[0]
                if lot[1] <= remaining:
                    remaining -= lot[1]
                    lots.popleft()
                else:
                    lot[1] -= remaining
                    remaining = 0
    while lots and today - lots[0][0] >= 365:
        lots.popleft()
    return sum(p for _, p in lots)
