def prune_backups(backups, now, free_mb, min_free_mb):
    now = int(now)
    free_mb = int(free_mb)
    min_free_mb = int(min_free_mb)

    to_delete = set()
    recent = []
    blocks = {}

    for b in backups:
        bid = b.get("id")
        if bid is None:
            continue

        if not b.get("ok", True):
            to_delete.add(bid)
            continue

        t = int(b.get("time", now))
        age = max(0, now - t)

        if age < 7 * DAY_MINUTES:
            recent.append(b)
        elif age < 28 * DAY_MINUTES:
            block = age // (7 * DAY_MINUTES)
            blocks.setdefault(block, []).append(b)
        else:
            to_delete.add(bid)

    retained = list(recent)

    for items in blocks.values():
        if not items:
            continue
        keep = max(
            items,
            key=lambda b: (int(b.get("time", now)), str(b.get("id", "")))
        )
        keep_id = keep.get("id")
        retained.append(keep)

        for b in items:
            if b.get("id") != keep_id:
                to_delete.add(b.get("id"))

    id_to_backup = {
        b.get("id"): b for b in backups if b.get("id") is not None
    }

    def size_of(bid):
        b = id_to_backup.get(bid)
        if b is None:
            return 0
        try:
            return max(0, int(b.get("size_mb", 0)))
        except (TypeError, ValueError):
            return 0

    deleted_size = sum(size_of(bid) for bid in to_delete)

    if free_mb + deleted_size < min_free_mb:
        need = min_free_mb - (free_mb + deleted_size)
        candidates = [b for b in retained if b.get("id") not in to_delete]
        candidates.sort(
            key=lambda b: (int(b.get("time", now)), str(b.get("id", "")))
        )

        for b in candidates:
            if need <= 0:
                break
            bid = b.get("id")
            to_delete.add(bid)
            sz = size_of(bid)
            deleted_size += sz
            need -= sz

    return sorted(to_delete, key=lambda x: str(x))
