def plan_meetings(requests, existing, now, tz):
    now = int(now)
    busy = []

    for iv in existing:
        try:
            s = int(iv["start"])
            e = int(iv["end"])
        except (KeyError, TypeError, ValueError):
            continue
        if e > s:
            busy.append((s, e))

    def overlaps(start, duration):
        if duration <= 0:
            return False
        end = start + duration
        for s, e in busy:
            if start < e and s < end:
                return True
        return False

    def earliest(start_from, duration):
        if duration <= 0:
            return start_from

        intervals = sorted(busy, key=lambda x: (x[0], x[1]))
        candidate = start_from

        for s, e in intervals:
            if e <= candidate:
                continue
            if s >= candidate + duration:
                break
            candidate = max(candidate, e)

        return candidate

    result = []

    for req in requests:
        rid = req.get("id")

        try:
            duration = int(req.get("duration", 0))
        except (TypeError, ValueError):
            duration = 0

        if duration < 0:
            duration = 0

        preferred = req.get("start", None)
        start = None

        if preferred is not None:
            try:
                pref = int(preferred)
            except (TypeError, ValueError):
                pref = None

            if pref is not None and pref >= now and not overlaps(pref, duration):
                start = pref

        if start is None:
            start = earliest(now, duration)

        if duration > 0:
            busy.append((start, start + duration))

        result.append({"id": rid, "start": start})

    return result
