from collections import deque


def loyalty_balance(events, today):
    today = int(today)

    def priority(kind):
        if kind == "earn":
            return 0
        if kind == "redeem":
            return 1
        if kind == "reverse":
            return 2
        return 3

    indexed = []

    for e in events:
        try:
            day = int(e.get("day"))
        except (TypeError, ValueError):
            continue

        if day <= today:
            indexed.append(
                (day, priority(e.get("kind")), str(e.get("id", "")), e)
            )

    indexed.sort(key=lambda x: (x[0], x[1], x[2]))
    ordered = [item[3] for item in indexed]

    canceled = set()
    active = set()

    for e in reversed(ordered):
        eid = e.get("id")
        if eid is None:
            continue
        if eid in canceled:
            continue

        active.add(eid)

        if e.get("kind") == "reverse":
            target = e.get("of")
            if target is not None:
                canceled.add(target)

    batches = deque()
    total = 0

    def expire(day):
        nonlocal total
        while batches and batches[0][1] <= day:
            total -= batches.popleft()[0]

    for e in ordered:
        eid = e.get("id")
        if eid not in active:
            continue

        kind = e.get("kind")

        try:
            day = int(e.get("day"))
        except (TypeError, ValueError):
            continue

        if kind == "earn":
            expire(day)

            try:
                pts = int(e.get("points", 0))
            except (TypeError, ValueError):
                pts = 0

            if pts > 0:
                batches.append([pts, day + 365])
                total += pts

        elif kind == "redeem":
            expire(day)

            try:
                pts = int(e.get("points", 0))
            except (TypeError, ValueError):
                pts = 0

            if pts < 100:
                continue

            if total < pts:
                continue

            remaining = pts

            while remaining > 0 and batches:
                batch = batches[0]
                take = min(batch[0], remaining)
                batch[0] -= take
                total -= take
                remaining -= take

                if batch[0] == 0:
                    batches.popleft()

    expire(today)
    return total
